SourceCode.Declaration:
/// COC extension for CustRecurrenceInvoiceUIBuilder to support MET toggle
/// that forces system date for invoice and generation dates and disable date controls.
/// </summary>
[ExtensionOf(classStr(CustRecurrenceInvoiceUIBuilder))]
internal final class METCustRecurrenceInvoiceUIBuilder_Extension
{
}

Method.Source:
/// <summary>
/// Initializes the dialog fields after the fields are built.
/// </summary>
public void postBuild()
{
    next postBuild();

    DialogField dialogRecurrenceInvoiceUseSystemDate;
    CustRecurrenceInvoiceDataContract custRecurrenceInvoiceDataContract = this.dataContractObject();
    dialogRecurrenceInvoiceUseSystemDate = this.bindInfo().getDialogField(
        custRecurrenceInvoiceDataContract,
        methodStr(CustRecurrenceInvoiceDataContract, parmUseSystemDateForRecurrence));
}

/// <summary>
/// Override postRun to apply use-system-date behaviour in the dialog.
/// </summary>
public void postRun()
{
    CustRecurrenceInvoiceDataContract contract = this.dataContractObject();
    DialogField dlgUseSystem;

    next postRun();

    // Get the dialog fields from binding info. If extension on contract is present the field will be available.
    dlgUseSystem = this.bindInfo().getDialogField(contract, methodStr(CustRecurrenceInvoiceDataContract, parmUseSystemDateForRecurrence));

    dlgUseSystem.registerOverrideMethod(
        methodStr(FormCheckBoxControl, modified),
        methodStr(METCustRecurrenceInvoiceUIBuilder_Extension, useSystemDateModified),
        this);
}

/// <summary>
/// Handles the modified event for the use-system-date checkbox.
/// </summary>
public boolean useSystemDateModified(FormCheckBoxControl _control)
{
    DialogField dlgUseSystem                = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(CustRecurrenceInvoiceDataContract, parmUseSystemDateForRecurrence));
    DialogField dlgRecurrenceGenerationDate = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(CustRecurrenceInvoiceDataContract, parmRecurrenceGenerationDate));
    DialogField dlgRecurrenceInvoiceDate    = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(CustRecurrenceInvoiceDataContract, parmRecurrenceInvoiceDate));

    boolean ret = _control.modified();

    if (dlgUseSystem && dlgRecurrenceGenerationDate && dlgRecurrenceInvoiceDate)
    {
        boolean useSystem = dlgUseSystem.value();

        // Disable/enable date controls based on toggle
        dlgRecurrenceGenerationDate.fieldControl().enabled(!useSystem);
        dlgRecurrenceInvoiceDate.fieldControl().enabled(!useSystem);

        if (useSystem)
        {
            TransDate systemDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            // set displayed values in dialog
            dlgRecurrenceGenerationDate.value(systemDate);
            dlgRecurrenceInvoiceDate.value(systemDate);
        }
    }

    return ret;
}
